"""Exceptions used by minisql."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Tokenizer and parser for the small SQL dialect described in SPEC.md."""

from ._errors import QueryError


KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER LIMIT OFFSET AS ASC DESC
    AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

AGGREGATES = frozenset(("COUNT", "SUM", "AVG", "MIN", "MAX"))

# Function name -> (minimum arguments, maximum arguments or None for no limit).
SCALAR_FUNCTIONS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


# ---------------------------------------------------------------------------
# Tokens


class Token:
    __slots__ = ("kind", "value", "text", "start", "end", "quoted")

    def __init__(self, kind, value, text, start, end, quoted=False):
        self.kind = kind
        self.value = value
        self.text = text
        self.start = start
        self.end = end
        self.quoted = quoted

    def __repr__(self):
        return "Token(%r, %r)" % (self.kind, self.value)


def _is_letter(ch):
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z")


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return _is_letter(ch) or ch == "_"


def _is_ident_char(ch):
    return _is_letter(ch) or _is_digit(ch) or ch == "_"


def _scan_quoted(sql, start, quote):
    """Scan a quoted string/identifier, returning (value, end)."""
    index = start + 1
    pieces = []
    length = len(sql)
    while index < length:
        ch = sql[index]
        if ch == quote:
            if index + 1 < length and sql[index + 1] == quote:
                pieces.append(quote)
                index += 2
                continue
            return "".join(pieces), index + 1
        pieces.append(ch)
        index += 1
    if quote == "'":
        raise QueryError("unterminated string literal")
    raise QueryError("unterminated quoted name")


def _scan_number(sql, start):
    length = len(sql)
    if sql[start] == ".":
        index = start + 1
        while index < length and _is_digit(sql[index]):
            index += 1
        return float(sql[start:index]), index

    index = start
    while index < length and _is_digit(sql[index]):
        index += 1
    if index < length and sql[index] == ".":
        index += 1
        while index < length and _is_digit(sql[index]):
            index += 1
        return float(sql[start:index]), index
    return int(sql[start:index]), index


def tokenize(sql):
    tokens = []
    index = 0
    length = len(sql)
    while index < length:
        ch = sql[index]

        if ch.isspace():
            index += 1
            continue

        if ch == "'":
            value, end = _scan_quoted(sql, index, "'")
            tokens.append(Token("STRING", value, sql[index:end], index, end))
            index = end
            continue

        if ch == '"':
            value, end = _scan_quoted(sql, index, '"')
            tokens.append(
                Token("IDENT", value, sql[index:end], index, end, quoted=True)
            )
            index = end
            continue

        if _is_digit(ch) or (ch == "." and index + 1 < length and _is_digit(sql[index + 1])):
            value, end = _scan_number(sql, index)
            tokens.append(Token("NUMBER", value, sql[index:end], index, end))
            index = end
            continue

        if _is_ident_start(ch):
            end = index + 1
            while end < length and _is_ident_char(sql[end]):
                end += 1
            tokens.append(Token("IDENT", sql[index:end], sql[index:end], index, end))
            index = end
            continue

        two = sql[index : index + 2]
        if two in ("!=", "<>", "<=", ">=", "||"):
            tokens.append(Token("OP", two, two, index, index + 2))
            index += 2
            continue

        if ch in "=<>+-*/(),;":
            tokens.append(Token("OP", ch, ch, index, index + 1))
            index += 1
            continue

        raise QueryError("unexpected character %r" % ch)

    tokens.append(Token("EOF", None, "", length, length))
    return tokens


# ---------------------------------------------------------------------------
# AST


class Expr:
    def __init__(self, start, end):
        self.start = start
        self.end = end


class Literal(Expr):
    def __init__(self, value, start, end):
        super().__init__(start, end)
        self.value = value


class ColumnRef(Expr):
    def __init__(self, name, start, end, name_start=None, name_end=None):
        super().__init__(start, end)
        self.name = name
        self.name_start = start if name_start is None else name_start
        self.name_end = end if name_end is None else name_end
        self.index = None


class Star(Expr):
    """The ``*`` used as an aggregate argument, e.g. ``COUNT(*)``."""


class Unary(Expr):
    def __init__(self, op, operand, start, end):
        super().__init__(start, end)
        self.op = op
        self.operand = operand


class Binary(Expr):
    def __init__(self, op, left, right, start, end):
        super().__init__(start, end)
        self.op = op
        self.left = left
        self.right = right


class IsNull(Expr):
    def __init__(self, operand, negated, start, end):
        super().__init__(start, end)
        self.operand = operand
        self.negated = negated


class InList(Expr):
    def __init__(self, operand, items, negated, start, end):
        super().__init__(start, end)
        self.operand = operand
        self.items = items
        self.negated = negated


class Between(Expr):
    def __init__(self, operand, low, high, negated, start, end):
        super().__init__(start, end)
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated


class Like(Expr):
    def __init__(self, operand, pattern, negated, start, end):
        super().__init__(start, end)
        self.operand = operand
        self.pattern = pattern
        self.negated = negated


class FunctionCall(Expr):
    def __init__(self, name, args, is_aggregate, start, end):
        super().__init__(start, end)
        self.name = name
        self.args = args
        self.is_aggregate = is_aggregate


class Query:
    def __init__(
        self,
        distinct,
        select_all,
        select_items,
        table,
        where,
        group_by,
        having,
        order_by,
        limit,
        offset,
        sql,
    ):
        self.distinct = distinct
        self.select_all = select_all
        self.select_items = select_items
        self.table = table
        self.where = where
        self.group_by = group_by
        self.having = having
        self.order_by = order_by
        self.limit = limit
        self.offset = offset
        self.sql = sql


class OrderItem:
    def __init__(self, expr, descending):
        self.expr = expr
        self.descending = descending


# ---------------------------------------------------------------------------
# Parser


class Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    def _peek(self, offset=0):
        pos = self.pos + offset
        if pos >= len(self.tokens):
            pos = len(self.tokens) - 1
        return self.tokens[pos]

    def _advance(self):
        token = self.tokens[self.pos]
        if token.kind != "EOF":
            self.pos += 1
        return token

    def _keyword(self, token=None):
        if token is None:
            token = self._peek()
        if token.kind == "IDENT" and not token.quoted:
            upper = token.value.upper()
            if upper in KEYWORDS:
                return upper
        return None

    def _is_keyword(self, keyword):
        return self._keyword() == keyword

    def _match_keyword(self, keyword):
        if self._is_keyword(keyword):
            self._advance()
            return True
        return False

    def _expect_keyword(self, keyword):
        if not self._match_keyword(keyword):
            self._error("expected %s" % keyword)
        return True

    def _is_op(self, op):
        token = self._peek()
        return token.kind == "OP" and token.value == op

    def _match_op(self, op):
        if self._is_op(op):
            self._advance()
            return True
        return False

    def _expect_op(self, op):
        if not self._match_op(op):
            self._error("expected %r" % op)
        return self.tokens[self.pos - 1]

    def _can_be_name(self, token):
        return token.kind == "IDENT" and (
            token.quoted or token.value.upper() not in KEYWORDS
        )

    def _parse_name(self):
        token = self._peek()
        if not self._can_be_name(token):
            self._error("expected a name")
        self._advance()
        return token.value

    def _parse_integer(self):
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int):
            self._error("expected an integer")
        self._advance()
        return token.value

    def _error(self, message):
        token = self._peek()
        if token.kind == "EOF":
            found = "end of query"
        else:
            found = repr(token.text)
        raise QueryError("%s near %s" % (message, found))

    # -- query -------------------------------------------------------------

    def parse(self):
        self._expect_keyword("SELECT")
        distinct = self._match_keyword("DISTINCT")

        select_all = False
        select_items = []
        if self._match_op("*"):
            select_all = True
        else:
            while True:
                expr = self._parse_expr()
                alias = None
                if self._match_keyword("AS"):
                    alias = self._parse_name()
                elif self._can_be_name(self._peek()):
                    alias = self._parse_name()
                select_items.append((expr, alias))
                if not self._match_op(","):
                    break

        self._expect_keyword("FROM")
        table = self._parse_name()

        where = None
        if self._match_keyword("WHERE"):
            where = self._parse_expr()

        group_by = []
        if self._match_keyword("GROUP"):
            self._expect_keyword("BY")
            while True:
                group_by.append(self._parse_expr())
                if not self._match_op(","):
                    break

        having = None
        if self._match_keyword("HAVING"):
            having = self._parse_expr()

        order_by = []
        if self._match_keyword("ORDER"):
            self._expect_keyword("BY")
            while True:
                expr = self._parse_expr()
                descending = False
                if self._match_keyword("DESC"):
                    descending = True
                else:
                    self._match_keyword("ASC")
                order_by.append(OrderItem(expr, descending))
                if not self._match_op(","):
                    break

        limit = None
        offset = None
        if self._match_keyword("LIMIT"):
            limit = self._parse_integer()
            if self._match_keyword("OFFSET"):
                offset = self._parse_integer()

        self._match_op(";")

        if self._peek().kind != "EOF":
            self._error("unexpected token")

        return Query(
            distinct,
            select_all,
            select_items,
            table,
            where,
            group_by,
            having,
            order_by,
            limit,
            offset,
            self.sql,
        )

    # -- expressions -------------------------------------------------------

    def _parse_expr(self):
        return self._parse_or()

    def _parse_or(self):
        left = self._parse_and()
        while self._is_keyword("OR"):
            self._advance()
            right = self._parse_and()
            left = Binary("OR", left, right, left.start, right.end)
        return left

    def _parse_and(self):
        left = self._parse_not()
        while self._is_keyword("AND"):
            self._advance()
            right = self._parse_not()
            left = Binary("AND", left, right, left.start, right.end)
        return left

    def _parse_not(self):
        if self._is_keyword("NOT"):
            token = self._advance()
            operand = self._parse_not()
            return Unary("NOT", operand, token.start, operand.end)
        return self._parse_comparison()

    def _parse_comparison(self):
        left = self._parse_additive()
        token = self._peek()

        if self._is_keyword("IS"):
            self._advance()
            negated = self._match_keyword("NOT")
            self._expect_keyword("NULL")
            return IsNull(left, negated, left.start, self.tokens[self.pos - 1].end)

        negated = False
        keyword = self._keyword(token)
        if keyword == "NOT" and self._keyword(self._peek(1)) in (
            "IN",
            "BETWEEN",
            "LIKE",
        ):
            self._advance()
            negated = True
            token = self._peek()
            keyword = self._keyword(token)

        if keyword == "IN":
            self._advance()
            self._expect_op("(")
            if self._is_op(")"):
                self._error("expected an expression")
            items = []
            while True:
                items.append(self._parse_expr())
                if not self._match_op(","):
                    break
            end = self._expect_op(")").end
            return InList(left, items, negated, left.start, end)

        if keyword == "BETWEEN":
            self._advance()
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return Between(left, low, high, negated, left.start, high.end)

        if keyword == "LIKE":
            self._advance()
            pattern = self._parse_additive()
            return Like(left, pattern, negated, left.start, pattern.end)

        if token.kind == "OP" and token.value in (
            "=",
            "!=",
            "<>",
            "<",
            "<=",
            ">",
            ">=",
        ):
            self._advance()
            right = self._parse_additive()
            op = "!=" if token.value == "<>" else token.value
            return Binary(op, left, right, left.start, right.end)

        return left

    def _parse_additive(self):
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("+", "-", "||"):
                self._advance()
                right = self._parse_multiplicative()
                left = Binary(token.value, left, right, left.start, right.end)
            else:
                break
        return left

    def _parse_multiplicative(self):
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "OP" and token.value in ("*", "/"):
                self._advance()
                right = self._parse_unary()
                left = Binary(token.value, left, right, left.start, right.end)
            else:
                break
        return left

    def _parse_unary(self):
        token = self._peek()
        if token.kind == "OP" and token.value == "-":
            self._advance()
            operand = self._parse_unary()
            return Unary("-", operand, token.start, operand.end)
        return self._parse_atom()

    def _parse_atom(self):
        token = self._peek()

        if token.kind == "OP" and token.value == "(":
            self._advance()
            expr = self._parse_expr()
            close = self._expect_op(")")
            # Keep the source span of the parenthesised expression so that its
            # default output name includes the parentheses when they are used.
            expr.start = token.start
            expr.end = close.end
            return expr

        if token.kind == "NUMBER":
            self._advance()
            return Literal(token.value, token.start, token.end)

        if token.kind == "STRING":
            self._advance()
            return Literal(token.value, token.start, token.end)

        if token.kind == "IDENT":
            keyword = self._keyword(token)
            if keyword == "NULL":
                self._advance()
                return Literal(None, token.start, token.end)
            if keyword == "TRUE":
                self._advance()
                return Literal(True, token.start, token.end)
            if keyword == "FALSE":
                self._advance()
                return Literal(False, token.start, token.end)

            if not token.quoted and keyword is not None:
                self._error("expected an expression")
            if not token.quoted and token.value.upper() in KEYWORDS:
                self._error("expected an expression")

            self._advance()
            if self._is_op("("):
                return self._parse_function(token)
            return ColumnRef(
                token.value, token.start, token.end, token.start, token.end
            )

        self._error("expected an expression")

    def _parse_function(self, name_token):
        self._expect_op("(")
        args = []
        if not self._is_op(")"):
            while True:
                if self._is_op("*"):
                    star = self._advance()
                    args.append(Star(star.start, star.end))
                else:
                    args.append(self._parse_expr())
                if not self._match_op(","):
                    break
        close = self._expect_op(")")

        name = name_token.value.upper()
        if name in AGGREGATES:
            if len(args) != 1:
                raise QueryError(
                    "%s takes exactly one argument" % name_token.value
                )
            if isinstance(args[0], Star) and name != "COUNT":
                raise QueryError(
                    "%s does not accept '*'" % name_token.value
                )
            is_aggregate = True
        elif name in SCALAR_FUNCTIONS:
            if any(isinstance(arg, Star) for arg in args):
                raise QueryError("%s does not accept '*'" % name_token.value)
            minimum, maximum = SCALAR_FUNCTIONS[name]
            count = len(args)
            if count < minimum or (maximum is not None and count > maximum):
                if minimum == maximum:
                    message = "%s takes exactly %d argument%s" % (
                        name_token.value,
                        minimum,
                        "" if minimum == 1 else "s",
                    )
                elif maximum is None:
                    message = "%s takes at least %d argument%s" % (
                        name_token.value,
                        minimum,
                        "" if minimum == 1 else "s",
                    )
                else:
                    message = "%s takes between %d and %d arguments" % (
                        name_token.value,
                        minimum,
                        maximum,
                    )
                raise QueryError(message)
            is_aggregate = False
        else:
            raise QueryError("unknown function %s" % name_token.value)

        return FunctionCall(
            name,
            args,
            is_aggregate,
            name_token.start,
            close.end,
        )


def parse_query(sql):
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return Parser(sql).parse()

"""Execution engine for minisql."""

import csv
import os
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from functools import cmp_to_key, lru_cache

from ._errors import QueryError
from ._parser import (
    Between,
    Binary,
    ColumnRef,
    FunctionCall,
    InList,
    IsNull,
    Like,
    Literal,
    Star,
    Unary,
    parse_query,
)


_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?[0-9]+\.[0-9]*\Z|-?[0-9]*\.[0-9]+\Z")


class QueryResult:
    """The result of :func:`minisql.run`."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):
        return "QueryResult(columns=%r, rows=%r)" % (self.columns, self.rows)


class _OrderInfo:
    def __init__(self, expr, descending, output_index):
        self.expr = expr
        self.descending = descending
        self.output_index = output_index


# ---------------------------------------------------------------------------
# Loading tables


def _convert_field(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def _load_table(directory, name):
    path = os.path.join(os.fspath(directory), name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8") as stream:
            reader = csv.reader(stream)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError("table %r has no header" % name)
            rows = []
            for record in reader:
                if not record:
                    continue
                row = []
                for index in range(len(header)):
                    if index < len(record):
                        row.append(_convert_field(record[index]))
                    else:
                        row.append(None)
                rows.append(row)
    except FileNotFoundError:
        raise QueryError("table %r not found (%s)" % (name, path))
    except OSError as error:
        raise QueryError("cannot read table %r: %s" % (name, error))
    return header, rows


# ---------------------------------------------------------------------------
# Expression utilities


def _children(expr):
    if isinstance(expr, Unary):
        return [expr.operand]
    if isinstance(expr, Binary):
        return [expr.left, expr.right]
    if isinstance(expr, IsNull):
        return [expr.operand]
    if isinstance(expr, InList):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, Between):
        return [expr.operand, expr.low, expr.high]
    if isinstance(expr, Like):
        return [expr.operand, expr.pattern]
    if isinstance(expr, FunctionCall):
        return list(expr.args)
    return []


def _resolve_expr(expr, lookup):
    if isinstance(expr, ColumnRef):
        index = lookup.get(expr.name.casefold())
        if index is None:
            raise QueryError("unknown column %r" % expr.name)
        expr.index = index
        return
    if isinstance(expr, (Literal, Star)):
        return
    for child in _children(expr):
        _resolve_expr(child, lookup)


def _contains_aggregate(expr):
    if isinstance(expr, FunctionCall):
        if expr.is_aggregate:
            return True
    for child in _children(expr):
        if _contains_aggregate(child):
            return True
    return False


def _validate_aggregates(expr, context, inside_aggregate=False):
    if isinstance(expr, FunctionCall) and expr.is_aggregate:
        if context in ("where", "group"):
            raise QueryError(
                "aggregate function %s is not allowed in %s"
                % (expr.name, "WHERE" if context == "where" else "GROUP BY")
            )
        if inside_aggregate:
            raise QueryError("aggregate functions cannot be nested")
        for arg in expr.args:
            _validate_aggregates(arg, context, True)
        return
    for child in _children(expr):
        _validate_aggregates(child, context, inside_aggregate)


def _expr_equal(left, right):
    if left.__class__ is not right.__class__:
        return False
    if isinstance(left, Literal):
        return type(left.value) is type(right.value) and left.value == right.value
    if isinstance(left, ColumnRef):
        return left.name.casefold() == right.name.casefold()
    if isinstance(left, Star):
        return True
    if isinstance(left, Unary):
        return left.op == right.op and _expr_equal(left.operand, right.operand)
    if isinstance(left, Binary):
        return (
            left.op == right.op
            and _expr_equal(left.left, right.left)
            and _expr_equal(left.right, right.right)
        )
    if isinstance(left, IsNull):
        return left.negated == right.negated and _expr_equal(
            left.operand, right.operand
        )
    if isinstance(left, InList):
        return (
            left.negated == right.negated
            and _expr_equal(left.operand, right.operand)
            and len(left.items) == len(right.items)
            and all(_expr_equal(a, b) for a, b in zip(left.items, right.items))
        )
    if isinstance(left, Between):
        return (
            left.negated == right.negated
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.low, right.low)
            and _expr_equal(left.high, right.high)
        )
    if isinstance(left, Like):
        return (
            left.negated == right.negated
            and _expr_equal(left.operand, right.operand)
            and _expr_equal(left.pattern, right.pattern)
        )
    if isinstance(left, FunctionCall):
        return (
            left.name.upper() == right.name.upper()
            and left.is_aggregate == right.is_aggregate
            and len(left.args) == len(right.args)
            and all(_expr_equal(a, b) for a, b in zip(left.args, right.args))
        )
    return False


def _validate_group_expression(expr, group_expressions):
    if any(_expr_equal(expr, group) for group in group_expressions):
        return

    if isinstance(expr, Literal):
        return
    if isinstance(expr, FunctionCall) and expr.is_aggregate:
        return
    if isinstance(expr, Star):
        return
    if isinstance(expr, ColumnRef):
        raise QueryError(
            "column %r must appear in GROUP BY or be used in an aggregate"
            % expr.name
        )

    for child in _children(expr):
        _validate_group_expression(child, group_expressions)


def _is_bare_integer(expr, sql):
    if not isinstance(expr, Literal):
        return False
    if not isinstance(expr.value, int) or isinstance(expr.value, bool):
        return False
    return re.fullmatch(r"[0-9]+", sql[expr.start : expr.end]) is not None


def _is_bare_column(expr):
    return (
        isinstance(expr, ColumnRef)
        and expr.start == expr.name_start
        and expr.end == expr.name_end
    )


# ---------------------------------------------------------------------------
# Values and operators


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, str):
        return "string"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    return type(value).__name__


def _compare_values(left, right):
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, bool) and isinstance(right, bool):
        if left is right:
            return 0
        return -1 if left is False else 1
    raise QueryError(
        "cannot compare %s with %s" % (_type_name(left), _type_name(right))
    )


def _compare_op(op, left, right):
    if left is None or right is None:
        return None
    comparison = _compare_values(left, right)
    if op == "=":
        return comparison == 0
    if op == "!=":
        return comparison != 0
    if op == "<":
        return comparison < 0
    if op == "<=":
        return comparison <= 0
    if op == ">":
        return comparison > 0
    if op == ">=":
        return comparison >= 0
    raise QueryError("unknown comparison operator %r" % op)


def _truth(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    raise QueryError("expected a boolean, found %s" % _type_name(value))


def _sql_not(value):
    truth = _truth(value)
    if truth is None:
        return None
    return not truth


def _sql_and(left, right):
    left_truth = _truth(left)
    if left_truth is False:
        return False
    right_truth = _truth(right)
    if right_truth is False:
        return False
    if left_truth is None or right_truth is None:
        return None
    return True


def _to_text(value):
    return str(value)


@lru_cache(maxsize=128)
def _like_expression(pattern):
    pieces = []
    for char in pattern:
        if char == "%":
            pieces.append(".*")
        elif char == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(char))
    return re.compile("".join(pieces), re.DOTALL)


def _round_integer(value):
    if isinstance(value, int):
        return value
    try:
        quantized = Decimal(str(value)).quantize(
            Decimal(1), rounding=ROUND_HALF_UP
        )
        return int(quantized)
    except (InvalidOperation, ValueError):
        raise QueryError("cannot round %r" % value)


def _round_places(value, places):
    try:
        quantum = Decimal(1).scaleb(-places)
        quantized = Decimal(str(value)).quantize(
            quantum, rounding=ROUND_HALF_UP
        )
        return float(quantized)
    except (InvalidOperation, ValueError):
        raise QueryError("cannot round %r to %r decimal places" % (value, places))


def _eval_binary(expr, row, group_rows, lookup):
    op = expr.op

    if op in ("AND", "OR"):
        left = _truth(_eval_expr(expr.left, row, group_rows, lookup))
        if op == "AND" and left is False:
            return False
        if op == "OR" and left is True:
            return True
        right = _truth(_eval_expr(expr.right, row, group_rows, lookup))
        if op == "AND":
            if right is False:
                return False
            if left is None or right is None:
                return None
            return True
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    left = _eval_expr(expr.left, row, group_rows, lookup)
    right = _eval_expr(expr.right, row, group_rows, lookup)

    if op in ("=", "!=", "<", "<=", ">", ">="):
        return _compare_op(op, left, right)

    if left is None or right is None:
        return None

    if op in ("+", "-", "*"):
        if not _is_number(left) or not _is_number(right):
            raise QueryError(
                "arithmetic requires numbers, found %s and %s"
                % (_type_name(left), _type_name(right))
            )
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        else:
            result = left * right
        if isinstance(left, int) and isinstance(right, int):
            return int(result)
        return float(result)

    if op == "/":
        if not _is_number(left) or not _is_number(right):
            raise QueryError(
                "arithmetic requires numbers, found %s and %s"
                % (_type_name(left), _type_name(right))
            )
        if right == 0:
            return None
        return float(left) / float(right)

    if op == "||":
        return _to_text(left) + _to_text(right)

    raise QueryError("unknown operator %r" % op)


def _eval_aggregate(expr, group_rows, lookup):
    if group_rows is None:
        raise QueryError("aggregate used outside a grouped query")

    name = expr.name.upper()
    argument = expr.args[0]

    if isinstance(argument, Star):
        if name != "COUNT":
            raise QueryError("%s does not accept '*'" % name)
        return len(group_rows)

    values = [
        _eval_expr(argument, row, None, lookup) for row in group_rows
    ]

    if name == "COUNT":
        return sum(1 for value in values if value is not None)

    non_null = [value for value in values if value is not None]
    if not non_null:
        return None

    if name in ("SUM", "AVG"):
        total = 0
        any_float = False
        for value in non_null:
            if not _is_number(value):
                raise QueryError(
                    "%s requires numbers, found %s" % (name, _type_name(value))
                )
            if isinstance(value, float):
                any_float = True
            total = total + value
        if name == "AVG":
            return float(total) / len(non_null)
        if any_float:
            return float(total)
        return int(total)

    if name in ("MIN", "MAX"):
        best = non_null[0]
        for value in non_null[1:]:
            comparison = _compare_values(value, best)
            if (name == "MIN" and comparison < 0) or (
                name == "MAX" and comparison > 0
            ):
                best = value
        return best

    raise QueryError("unknown aggregate function %s" % name)


def _eval_scalar(expr, row, group_rows, lookup):
    name = expr.name.upper()

    if name == "COALESCE":
        for argument in expr.args:
            value = _eval_expr(argument, row, group_rows, lookup)
            if value is not None:
                return value
        return None

    values = [
        _eval_expr(argument, row, group_rows, lookup) for argument in expr.args
    ]
    if any(value is None for value in values):
        return None

    if name == "LOWER":
        if not isinstance(values[0], str):
            raise QueryError("LOWER requires a string")
        return values[0].lower()
    if name == "UPPER":
        if not isinstance(values[0], str):
            raise QueryError("UPPER requires a string")
        return values[0].upper()
    if name == "LENGTH":
        if not isinstance(values[0], str):
            raise QueryError("LENGTH requires a string")
        return len(values[0])
    if name == "ABS":
        if not _is_number(values[0]):
            raise QueryError("ABS requires a number")
        return abs(values[0])
    if name == "ROUND":
        if not _is_number(values[0]):
            raise QueryError("ROUND requires a number")
        if len(values) == 1:
            return _round_integer(values[0])
        if not isinstance(values[1], int) or isinstance(values[1], bool):
            raise QueryError("ROUND requires an integer number of places")
        return _round_places(values[0], values[1])

    raise QueryError("unknown function %s" % name)


def _eval_expr(expr, row, group_rows, lookup):
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, ColumnRef):
        if expr.index is None:
            raise QueryError("unresolved column %r" % expr.name)
        if row is None:
            raise QueryError("column %r is not available" % expr.name)
        return row[expr.index]

    if isinstance(expr, Star):
        raise QueryError("'*' is not allowed here")

    if isinstance(expr, Unary):
        value = _eval_expr(expr.operand, row, group_rows, lookup)
        if expr.op == "NOT":
            return _sql_not(value)
        if expr.op == "-":
            if value is None:
                return None
            if not _is_number(value):
                raise QueryError("unary - requires a number")
            return -value
        raise QueryError("unknown unary operator %r" % expr.op)

    if isinstance(expr, Binary):
        return _eval_binary(expr, row, group_rows, lookup)

    if isinstance(expr, IsNull):
        value = _eval_expr(expr.operand, row, group_rows, lookup)
        result = value is None
        return not result if expr.negated else result

    if isinstance(expr, InList):
        value = _eval_expr(expr.operand, row, group_rows, lookup)
        if value is None:
            result = None
        else:
            result = False
            saw_null = False
            for item in expr.items:
                item_value = _eval_expr(item, row, group_rows, lookup)
                if item_value is None:
                    saw_null = True
                    continue
                if _compare_op("=", value, item_value):
                    result = True
                    break
            else:
                if saw_null:
                    result = None
        if expr.negated and result is not None:
            result = not result
        return result

    if isinstance(expr, Between):
        value = _eval_expr(expr.operand, row, group_rows, lookup)
        low = _eval_expr(expr.low, row, group_rows, lookup)
        left = _compare_op("<=", low, value)
        if left is False:
            result = False
        else:
            high = _eval_expr(expr.high, row, group_rows, lookup)
            right = _compare_op("<=", value, high)
            result = _sql_and(left, right)
        if expr.negated and result is not None:
            result = not result
        return result

    if isinstance(expr, Like):
        value = _eval_expr(expr.operand, row, group_rows, lookup)
        pattern = _eval_expr(expr.pattern, row, group_rows, lookup)
        if value is None or pattern is None:
            result = None
        else:
            if not isinstance(value, str) or not isinstance(pattern, str):
                raise QueryError("LIKE requires strings")
            result = _like_expression(pattern).fullmatch(value) is not None
        if expr.negated and result is not None:
            result = not result
        return result

    if isinstance(expr, FunctionCall):
        if expr.is_aggregate:
            return _eval_aggregate(expr, group_rows, lookup)
        return _eval_scalar(expr, row, group_rows, lookup)

    raise QueryError("internal error: unknown expression")


# ---------------------------------------------------------------------------
# Grouping, ordering, distinct


def _canonical_value(value):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("boolean", value)
    if _is_number(value):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    return ("other", value)


def _filter_rows(rows, condition, lookup):
    if condition is None:
        return list(rows)
    kept = []
    for row in rows:
        value = _eval_expr(condition, row, None, lookup)
        if _truth(value) is True:
            kept.append(row)
    return kept


def _build_groups(rows, group_by, lookup):
    if not group_by:
        # Without GROUP BY, all rows form one group even when there are none.
        return [list(rows)]

    groups_by_key = {}
    groups = []
    for row in rows:
        key = tuple(
            _canonical_value(_eval_expr(expr, row, None, lookup))
            for expr in group_by
        )
        group = groups_by_key.get(key)
        if group is None:
            group = []
            groups_by_key[key] = group
            groups.append(group)
        group.append(row)
    return groups


def _order_keys(order_info, output_row, row, group_rows, lookup):
    keys = []
    for info in order_info:
        if info.output_index is not None:
            keys.append(output_row[info.output_index])
        else:
            keys.append(_eval_expr(info.expr, row, group_rows, lookup))
    return keys


def _compare_records(left_keys, right_keys, order_info):
    for left, right, info in zip(left_keys, right_keys, order_info):
        if left is None and right is None:
            continue
        if left is None:
            return 1 if info.descending else -1
        if right is None:
            return -1 if info.descending else 1
        comparison = _compare_values(left, right)
        if comparison != 0:
            return -comparison if info.descending else comparison
    return 0


# ---------------------------------------------------------------------------
# Public entry point


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    query = parse_query(sql)
    header, rows = _load_table(directory, query.table)

    lookup = {}
    for index, name in enumerate(header):
        lookup.setdefault(name.casefold(), index)

    if query.where is not None:
        _validate_aggregates(query.where, "where")
    for expression in query.group_by:
        _validate_aggregates(expression, "group")
    for expression, _alias in query.select_items:
        _validate_aggregates(expression, "select")
    if query.having is not None:
        _validate_aggregates(query.having, "having")
    for item in query.order_by:
        _validate_aggregates(item.expr, "order")

    if query.where is not None:
        _resolve_expr(query.where, lookup)
    for expression in query.group_by:
        _resolve_expr(expression, lookup)
    for expression, _alias in query.select_items:
        _resolve_expr(expression, lookup)
    if query.having is not None:
        _resolve_expr(query.having, lookup)

    # Build the output expressions and their names.
    select_expressions = []
    columns = []
    if query.select_all:
        for index, name in enumerate(header):
            reference = ColumnRef(name, -1, -1, -1, -1)
            reference.index = index
            select_expressions.append(reference)
            columns.append(name)
    else:
        for expression, alias in query.select_items:
            if alias is not None:
                name = alias
            elif _is_bare_column(expression):
                name = header[expression.index]
            else:
                name = sql[expression.start : expression.end]
            select_expressions.append(expression)
            columns.append(name)

    # Work out which ORDER BY items refer to output columns.
    order_info = []
    for item in query.order_by:
        output_index = None
        if _is_bare_integer(item.expr, sql):
            position = item.expr.value
            if position < 1 or position > len(columns):
                raise QueryError(
                    "ORDER BY position %d is out of range" % position
                )
            output_index = position - 1
        elif _is_bare_column(item.expr):
            wanted = item.expr.name.casefold()
            for index, name in enumerate(columns):
                if name.casefold() == wanted:
                    output_index = index
                    break
        if output_index is None:
            _resolve_expr(item.expr, lookup)
        order_info.append(_OrderInfo(item.expr, item.descending, output_index))

    grouped = (
        bool(query.group_by)
        or any(_contains_aggregate(expression) for expression in select_expressions)
        or (
            query.having is not None
            and _contains_aggregate(query.having)
        )
        or any(_contains_aggregate(info.expr) for info in order_info)
    )

    if grouped:
        for expression in select_expressions:
            _validate_group_expression(expression, query.group_by)
        if query.having is not None:
            _validate_group_expression(query.having, query.group_by)
        for info in order_info:
            if info.output_index is None:
                _validate_group_expression(info.expr, query.group_by)

    filtered = _filter_rows(rows, query.where, lookup)

    records = []
    if grouped:
        for group_rows in _build_groups(filtered, query.group_by, lookup):
            representative = group_rows[0] if group_rows else None
            if query.having is not None:
                having_value = _eval_expr(
                    query.having, representative, group_rows, lookup
                )
                if _truth(having_value) is not True:
                    continue
            output_row = tuple(
                _eval_expr(expression, representative, group_rows, lookup)
                for expression in select_expressions
            )
            keys = _order_keys(
                order_info, output_row, representative, group_rows, lookup
            )
            records.append((output_row, keys))
    else:
        for row in filtered:
            if query.having is not None:
                having_value = _eval_expr(query.having, row, None, lookup)
                if _truth(having_value) is not True:
                    continue
            output_row = tuple(
                _eval_expr(expression, row, None, lookup)
                for expression in select_expressions
            )
            keys = _order_keys(order_info, output_row, row, None, lookup)
            records.append((output_row, keys))

    if query.distinct:
        seen = set()
        distinct_records = []
        for output_row, keys in records:
            marker = tuple(_canonical_value(value) for value in output_row)
            if marker not in seen:
                seen.add(marker)
                distinct_records.append((output_row, keys))
        records = distinct_records

    if order_info:
        records.sort(
            key=cmp_to_key(
                lambda left, right: _compare_records(
                    left[1], right[1], order_info
                )
            )
        )

    if query.limit is not None:
        start = 0 if query.offset is None else query.offset
        end = start + query.limit
        records = records[start:end]

    return QueryResult(columns, [output_row for output_row, _keys in records])

